sys_ui_action.script:
// bfd_ui_initiate_chargeback — raise a chargeback task against the merchant
// and move the case into investigation if it is still earlier in the lifecycle.
(function initiateChargebackAction() {
    var TASK_TABLE = 'x_1755386_safetr_0_bfd_case_task';
    var EARLY = ',new,triage,pending_customer_information,reopened,';

    var task = new GlideRecord(TASK_TABLE);
    task.initialize();
    task.setValue('case', current.getUniqueValue());
    task.setValue('task_type', 'chargeback');
    task.setValue('status', 'open');
    task.setValue('priority', current.getValue('priority') || 'p2');
    task.setValue(
        'outcome',
        'Chargeback initiated by ' +
            gs.getUserDisplayName() +
            ' for disputed amount ' +
            (current.getValue('disputed_amount') || '0') +
            ' ' +
            (current.getValue('currency') || '')
    );
    if (current.getValue('assigned_group')) task.setValue('assigned_group', current.getValue('assigned_group'));
    var due = new GlideDateTime();
    due.addDaysLocalTime(10);
    task.setValue('due_date', due.getValue());
    task.insert();

    var statusNote = '';
    var status = current.getValue('case_status') || '';
    if (EARLY.indexOf(',' + status + ',') > -1) {
        current.setValue('case_status', 'under_investigation');
        statusNote = ' Case status moved from "' + status + '" to "under_investigation".';
    }

    new bfd_TriageEngine().logAiDecision(current, {
        note: 'Chargeback initiated. Task ' + task.getValue('number') + ' raised to the case group.' + statusNote,
        finalDecision: 'chargeback_initiated',
    });
    current.update();

    gs.addInfoMessage(
        'Chargeback initiated. Task ' +
            task.getValue('number') +
            ' has been raised to the assigned group with a 10 day due date.' +
            statusNote
    );
    action.setRedirectURL(current);
})();
